on conflict (id) do update
  set axis = excluded.axis,
      setting = excluded.setting,
      unflattering = excluded.unflattering,
      intake_slot = excluded.intake_slot,
      prompt = excluded.prompt,
      options = excluded.options,
      legacy_prompts = excluded.legacy_prompts,
      updated_at = now();

update public.question_bank
   set retired_at = now(), updated_at = now()
 where retired_at is null
   and id in ('extraversion_13', 'steadiness_09', 'attachment_anxiety_17', 'attachment_anxiety_21', 'attachment_anxiety_22', 'attachment_avoidance_09', 'attachment_avoidance_16', 'attachment_avoidance_24', 'attachment_avoidance_25', 'conflict_assertiveness_05', 'conflict_assertiveness_07', 'conflict_assertiveness_24', 'conflict_cooperativeness_08', 'conflict_cooperativeness_23', 'relatedness_15', 'locus_of_control_24', 'self_efficacy_04', 'self_efficacy_10', 'playfulness_21');

-- Every trait keeps exactly 25 active questions; anything else rolls the whole file back.
do $check$
declare
  bad text;
begin
  select string_agg(axis || '=' || n, ', ') into bad
    from (select axis, count(*) filter (where retired_at is null) as n
            from public.question_bank group by axis) t
   where n <> 25;
  if bad is not null then
    raise exception 'wave100b: each trait needs 25 active questions, got %', bad;
  end if;
end
$check$;
